SELECT '==G. ?EXISTEN GRADE_GRADES PARA LOS 11 ESTUDIANTES EN ITEM 2048?==' as '';
SELECT userid, finalgrade, rawgrade FROM isi_grade_grades WHERE itemid = 2048 AND userid IN (2009, 2068, 2278, 2328, 2490, 2507, 2515, 2518, 2548, 2558, 2755) ORDER BY userid;
SELECT '==H. SUBMISSION DETAILS PARA USER 2317 EN ASSIGN 256==' as '';
SELECT s.id AS submission_id, s.assignment, s.status, from_unixtime(s.timecreated) tc, from_unixtime(s.timemodified) tm, (SELECT COUNT(*) FROM isi_files f WHERE f.component = 'assignsubmission_file' AND f.itemid = s.id AND f.filename <> '.') AS file_count FROM isi_assign_submission s WHERE s.assignment = 256 AND s.userid = 2317 AND s.latest = 1;
SELECT '==I. ITEMID 65 EN ISI_FILES - CONFIRMAR QUE ES EL SUBMISSION VIEJO==' as '';
SELECT id, component, filearea, itemid, filename, filesize, userid FROM isi_files WHERE itemid = 65 AND filename <> '.';
SELECT '==J. GRADE_GRADES PARA ITEM 1766 AUN EXISTEN?==' as '';
SELECT COUNT(*) FROM isi_grade_grades WHERE itemid = 1766;
SELECT '==K. ASIGN_GRADES PARA ASSIGN 65 AUN EXISTEN?==' as '';
SELECT COUNT(*) FROM isi_assign_grades WHERE assignment = 65;
SELECT '==L. CONTEXTO ACTUAL DEL ASSIGN 256 SUBMISSIONS (solo para confirmar 2317)==' as '';
SELECT s.userid, u.firstname, u.lastname, s.id AS sub_id, s.status FROM isi_assign_submission s JOIN isi_user u ON u.id = s.userid WHERE s.assignment = 256 AND s.latest = 1 AND s.userid = 2317;
